python3 -c "
import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-business-rule-task/BusinessRuleDecision/BusinessRuleDecision/BusinessRuleDecision.bpmn')
root = tree.getroot()
ns = {
  'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
  'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
  'uipath': 'http://uipath.org/schema/bpmn'
}
errors = []

# 1. Root element check
assert root.tag == '{http://www.omg.org/spec/BPMN/20100524/MODEL}definitions', 'Missing definitions root'

# 2. All declared IDs
all_ids = {el.get('id') for el in root.iter() if el.get('id')}

# 3. Collect flow nodes with incoming/outgoing refs
proc = root.find('bpmn:process', ns)
seq_flows = {sf.get('id'): (sf.get('sourceRef'), sf.get('targetRef')) for sf in proc.findall('bpmn:sequenceFlow', ns)}

# 4. XOR gateway: default set, non-default flows have conditions
gws = proc.findall('bpmn:exclusiveGateway', ns)
for gw in gws:
    default = gw.get('default')
    outgoing = [o.text for o in gw.findall('bpmn:outgoing', ns)]
    for fid in outgoing:
        if fid == default: continue
        sf = proc.find(f'bpmn:sequenceFlow[@id=\"{fid}\"]', ns)
        cond = sf.find('bpmn:conditionExpression', ns) if sf is not None else None
        if cond is None:
            errors.append(f'Gateway {gw.get(\"id\")}: non-default flow {fid} missing conditionExpression')

# 5. Each node has at most one incoming flow
for tag in ['bpmn:startEvent','bpmn:endEvent','bpmn:businessRuleTask','bpmn:exclusiveGateway']:
    for el in proc.findall(tag, ns):
        inc = el.findall('bpmn:incoming', ns)
        if len(inc) > 1:
            errors.append(f'FAKE_JOIN on {el.get(\"id\")}: {len(inc)} incoming')

# 6. DI coverage
plane = root.find('.//bpmndi:BPMNPlane', ns)
shapes = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', ns)}
edges  = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', ns)}
flow_nodes = [el.get('id') for el in proc if el.get('id') and 'sequenceFlow' not in el.tag and 'extensionElements' not in el.tag]
for nid in flow_nodes:
    if nid not in shapes:
        errors.append(f'Missing shape for {nid}')
for fid in seq_flows:
    if fid not in edges:
        errors.append(f'Missing edge for {fid}')

# 7. All refs resolve
for sf in proc.findall('bpmn:sequenceFlow', ns):
    for attr in ('sourceRef','targetRef'):
        ref = sf.get(attr)
        if ref not in all_ids:
            errors.append(f'Unresolved {attr}={ref} in {sf.get(\"id\")}')

if errors:
    for e in errors: print('ERROR:', e)
    exit(1)
else:
    print('VALID - all structural checks passed')
"

